function SanGongRoomScene:ctor()
    cc.SpriteFrameCache:getInstance():addSpriteFrames(TpackageName .. '/csb/PokerCard/Plist.plist')
     --开局之后进入会来不急加载
    SanGongPanel = cc.CSLoader:createNode(TpackageName .. '/csb/GameSceneSector/GameSceneForTen.csb'):addTo(self)
    GameUtils.setNodeNameBindObj(SanGongPanel)
    SANGONG_GAME_SCENE = SanGongPanel:getChildByName('game_plane')
    SANGONG_GAME_SCENE:setVisible(false)
    SCREEN_WIDTH = cc.Director:getInstance():getOpenGLView():getDesignResolutionSize().width
    SCREEN_HEIGHT = cc.Director:getInstance():getOpenGLView():getDesignResolutionSize().height
    self:initUI()

    SanGongPanel:setScale(SCREEN_WIDTH / DESIGN_SCREEN_WIDTH, SCREEN_HEIGHT / DESIGN_SCREEN_HEIGHT)

    GamePlaneOperator = require(TpackageName .. '.operator.GamePlaneOperator')
    GamePlaneOperator:init()

    --添加牛牛版本号显示
    local lbVersion = cc.Label:createWithSystemFont(GAME_VERSION, 'Arial', 22)
    lbVersion:setColor(cc.c3b(125, 125, 125))
    lbVersion:setPosition(
        cc.p(
            SanGongPanel:getContentSize().width - lbVersion:getContentSize().width / 2,
            SanGongPanel:getContentSize().height - lbVersion:getContentSize().height / 2
        )
    )
    SanGongPanel:addChild(lbVersion, 1000)
    SanGongScene = self

    --显示表情符号
    local idx = ViewBase:getZOrderByChilds(self)
    local EmojiArmatureView =
        require('hall.EmojiArmatureView.EmojiArmatureView'):newEmojiArmatureView(
        self:getToSendFaceAndTxtFuncs(),
        SanGongScene
    )
    EmojiArmatureView:setLocalZOrder(idx)
    g_sangongMainScene = self
end

function SanGongRoomScene:loadLayerByName(path, zOrder, data)
    if path == nil then
        print('PDKgameScene:loadLayerByName [path] is nil ----------------------')
    end
    zOrder = zOrder == nil and self:getChildrenCount() + 1 or zOrder
    local layer = require(path).new(data)

    if not tolua.isnull(layer) then

        layer:addTo(self, zOrder)
    end

    return layer
end

