function SanGongRoomScene:getGameConfig()
    local tempT = string.split(RULE_PLAYER_DATA.base, ',')
    -- local tempS = ''
    -- tempS = tempS .. (tonumber(tempT[1])/100) .. '/'
    -- tempS = tempS .. (tonumber(tempT[2])/100) .. '/'
    -- tempS = tempS .. (tonumber(tempT[3])/100)
    local gameConfigTable = {
        {['人数'] = RULE_PLAYER_DATA.players},
        {['底分'] = initialChip},
        {['封顶'] = maxChip},
        {['开始'] = RULE_PLAYER_DATA.startCount == '0' and '手动开始' or '满' .. RULE_PLAYER_DATA.startCount .. '人开始'}
    }
    return gameConfigTable
end

