function SanGongRoomScene:onClickSlider(sender, eventType)
    if eventType == ccui.SliderEventType.percentChanged then
        local minInt = 5
        local curNum = tonumber(self.bei_txt:getString())
        local amount = sender:getPercent() / minInt
        amount = math.round(amount)
        amount = amount * minInt
        if amount < minInt then
            amount = minInt
        end
        self.bei_txt:setString(amount)
        sender:setPercent(amount)
        self._xiaZhuNumber = amount
    end
end

function SanGongRoomScene:_getScaleParam2()
    local frameHeight = CONFIG_WIN_HEIGHT
    local disHeight = CONFIG_DESIGN_HEIGHT
    return (CONFIG_WIN_WIDTH / CONFIG_DESIGN_WIDTH) * (disHeight / (frameHeight or 0))
end

function SanGongRoomScene:registShareButtons(invote_code)
    local invote_code = invote_code or ''
    local config_arr = LuaSplit(USER_INFO['gameConfig'], ' ')
    local share_content = ''
    for k, v in pairs(config_arr) do
        if v ~= '' then
            share_content = share_content .. v .. ','
        end
    end

    local hall_plane = SanGongPanel.hall_plane
    --邀请微信好友

    require('hall.util.GameMenu'):registCopyRoomIdFunc(self.copy_btn, invote_code, GAME_NAME)

    if isiOSVerify then
        self.copy_btn:setVisible(false)
        self.share_btn:setVisible(false)
    end

    local shareButtonFuc = function(sender, event)
        --触摸开始
        if event == TOUCH_EVENT_BEGAN then
            sender:setScale(0.9)
        end

        --触摸取消
        if event == TOUCH_EVENT_CANCELED then
            sender:setScale(1.0)
        end

        --触摸结束
        if event == TOUCH_EVENT_ENDED then
            sender:setScale(1.0)

            if sender == self.share_btn then
                local paras = {}
                paras['desc'] = USER_INFO['gameConfigMsg'] or ' '
                paras['imagePath'] = 'url'
                paras['name'] = '三公，房号：' .. USER_INFO['invote_code']
                paras['showType'] = 2
                paras['url'] = appDownLoadAddress
                local shareLayer = require('hall.share.ShareLayer').new(paras)
                if shareLayer then
                    shareLayer:addTo(SCENENOW['scene'], 9999999)
                end

            -- share_content = string.sub(share_content, 1, string.len(share_content) - 1)
            -- require("hall.common.ShareLayer"):showShareLayer(GAME_NAME .. "，房号：" .. invote_code, "http://download.doudougame.cn/app/index.html", "url", share_content)
            end
        end
    end

    self.share_btn:addTouchEventListener(shareButtonFuc)
    self:showShareButton(true)
end

function SanGongRoomScene:showWaiWeiButton(flag, ableBet)
    local hall_plane = SanGongPanel:getChildByName('hall_plane')
    local btn_switch_bet_mode = hall_plane:getChildByName('btn_switch_bet_mode')

    local effect_light = btn_switch_bet_mode:getChildByName('effect_light')
    local bottom_img = btn_switch_bet_mode:getChildByName('bottom_img')

    if flag ~= nil then
        btn_switch_bet_mode:setVisible(flag)

    -- --查看录纸
    -- local win_trend_bt = hall_plane:getChildByName("win_trend_bt")
    -- win_trend_bt:setVisible(flag)
    end

    if ableBet == true then
        bottom_img:setColor(cc.c3b(255, 255, 255))
        effect_light:setVisible(true)
        effect_light:runAction(
            cc.Repeat:create(
                cc.Spawn:create(
                    cc.Sequence:create(cc.ScaleTo:create(0.25, 0.5), cc.ScaleTo:create(0.25, 0.65)),
                    cc.RotateBy:create(0.5, 30)
                ),
                5
            )
        )
    elseif ableBet == false then
        effect_light:setVisible(false)
        bottom_img:setColor(cc.c3b(125, 125, 125))
        GamePlaneOperator:showWaiWeiButton(false)
    end
end

