--解散组局相关
--解散组局
function SanGongRoomScene:disbandGroup()
    local function disband()
        SanGongSendHandle:C2G_CMD_DISSOLVE_ROOM()
    end

    --查询用户当前的游戏状态来判断当前通过怎样的方式来解散组局
    cct.createHttRq(
        {
            url = HttpAddr .. '/freeGame/queryGroupGameStatus',
            date = {
                activityId = USER_INFO['activity_id'],
                interfaceType = 'j'
            },
            type_ = 'POST',
            callBack = function(data)
                local responseData = data.netData
                responseData = json.decode(responseData)
                local returnCode = responseData.returnCode
                if returnCode == '0' then
                    local data = tonumber(responseData.data)
                    if data == 1 then
                        --创建组局
                        if isiOSVerify then
                            require('hall.GameTips'):showDisbandTips(
                                '解散房间',
                                'new_disbandGroup',
                                1,
                                '是否解散房间？',
                                _,
                                disband
                            )
                        else
                            require('hall.GameTips'):showDisbandTips(
                                '解散房间',
                                'new_disbandGroup',
                                1,
                                '当前解散房间不需扣除房卡，是否解散？',
                                _,
                                disband
                            )
                        end
                    elseif data == 2 then
                        --开始组局
                        if isiOSVerify then
                            require('hall.GameTips'):showDisbandTips(
                                '解散房间',
                                'new_disbandGroup',
                                1,
                                '是否解散房间？',
                                _,
                                disband
                            )
                        else
                            require('hall.GameTips'):showDisbandTips(
                                '解散房间',
                                'new_disbandGroup',
                                1,
                                '当前已经扣除房卡，是否申请解散房间？',
                                _,
                                disband
                            )
                        end
                    elseif data == 0 then
                        --结束组局
                        require('hall.GameTips'):showTips('提示', 'tohall', 1, '当前组局已结束，是否返回大厅？')
                    end
                else
                end
            end
        }
    )
end

