--按照传入的分隔符，切割字符串
function LuaSplit(str, split_char)
    if str == '' or str == nil then
        return {}
    end
    local split_len = string.len(split_char)
    local sub_str_tab = {}
    local i = 0
    local j = 0
    while true do
        j = string.find(str, split_char, i + split_len) --从目标串str第i+split_len个字符开始搜索指定串
        if string.len(str) == i then
            break
        end

        if j == nil then
            table.insert(sub_str_tab, string.sub(str, i))
            break
        end

        table.insert(sub_str_tab, string.sub(str, i, j - 1))
        i = j + split_len
    end
    return sub_str_tab
end

function SanGongRoomScene:onExit()
    GamePlaneOperator:clearGameDatas()
    g_isWatch = nil
end

function SanGongRoomScene:onChangeBg()
    local str = cc.UserDefault:getInstance():getIntegerForKey('GameBgType', 1)
    local room_bg1 = SanGongPanel:getChildByName('background')
    room_bg1:loadTexture(TpackageName .. '/csb/GameSceneSector/bg_' .. str .. '.png')
end

